                if (!taxExempt && !Boolean.TRUE.equals(lineItems.get(n).get("taxExempt"))) {
                    BigDecimal flatShare = subtotal.signum() == 0 ? BigDecimal.ZERO
                            : sharedDiscount.multiply(line).divide(subtotal, 2, RoundingMode.HALF_UP);
                    BigDecimal base = line.subtract(
                            line.multiply(discountPct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP))
                            .subtract(flatShare);
                    tax = tax.add(base.multiply(taxPct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP));
                }
            }
            BigDecimal discount = pctDiscount.add(flatDiscount);
            BigDecimal discounted = subtotal.subtract(discount);
            // An invoice for a tax-inclusive client already has the tax inside its prices, so its amount is
            // just the discounted subtotal.
            // An early-payment discount offered is just recorded; it does not change the amount owed.
            BigDecimal earlyPaymentPct = i.get("earlyPaymentPct") == null ? BigDecimal.ZERO
                    : new BigDecimal(i.get("earlyPaymentPct").toString());
            // A flat surcharge (such as a handling fee) is added on last, after any tax.
            BigDecimal surcharge = i.get("surcharge") == null ? BigDecimal.ZERO
                    : new BigDecimal(i.get("surcharge").toString());
            // A minimum charge is billed instead when the net total comes out under it.
            BigDecimal minimumCharge = decimal(i.get("minimumCharge"));
            // A settlement rebate offered for paying before the due date is just recorded; it does not change the amount owed.
            BigDecimal rebatePct = decimal(i.get("rebatePct"));
            // An invoice may be billed in its own currency ("currency"); without one it is in its client's.
            // A late fee per day accrues once the invoice is overdue; it does not change the amount invoiced.
            BigDecimal lateFeePerDay = decimal(i.get("lateFeePerDay"));
            // Interest per day accrues on each instalment still unpaid past its due date.
            BigDecimal interestPerDay = decimal(i.get("interestPerDay"));
            // A percentage may be held back as retention; it is not due yet but does not change the amount invoiced.
            BigDecimal retentionPct = decimal(i.get("retentionPct"));
            // The retention may already have been released ("retentionReleased"), making it due.
            boolean retentionReleased = Boolean.TRUE.equals(i.get("retentionReleased"));
            // Part of the invoice may already have been written off as bad debt ("writeOff"), so it is no longer owed.
            // It may carry the client's purchase-order number ("poNumber"), and may be disputed by the client ("disputed").
            BigDecimal writeOff = decimal(i.get("writeOff"));
            jdbc.update("INSERT INTO invoice (id, project_id, amount, tax_pct, surcharge, tax_inclusive, tax_exempt,"
                    + " early_payment_pct, rebate_pct, status, issued_date, due_date, minimum_charge, late_fee_per_day, instalment_interest_per_day, retention_pct, retention_released, write_off_amount, currency, po_number, disputed)"
                    + " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    invoiceId, projectId,
                    (taxInclusive ? discounted : discounted.add(tax)).add(surcharge).max(minimumCharge), taxPct,
                    surcharge, taxInclusive, taxExempt,
                    earlyPaymentPct, rebatePct, seedStatus(i.get("status")), issued, due, minimumCharge, lateFeePerDay, interestPerDay, retentionPct,
                    retentionReleased, writeOff,
                    i.get("currency") == null ? null : i.get("currency").toString(),
                    i.get("poNumber") == null ? null : i.get("poNumber").toString(),
                    Boolean.TRUE.equals(i.get("disputed")));
            for (Map<String, Object> d : discounts) {
                if (d.get("id") != null) {
                    jdbc.update("INSERT INTO invoice_discount (id, invoice_id, discount_pct, discount_amount, discount_cap) VALUES (?, ?, ?, ?, ?)",
                            ((Number) d.get("id")).longValue(), invoiceId, decimal(d.get("pct")), decimal(d.get("amount")),
                            d.get("cap") == null ? null : decimal(d.get("cap")));
                } else {
                    jdbc.update("INSERT INTO invoice_discount (invoice_id, discount_pct, discount_amount, discount_cap) VALUES (?, ?, ?, ?)",
                            invoiceId, decimal(d.get("pct")), decimal(d.get("amount")), d.get("cap") == null ? null : decimal(d.get("cap")));
                }
            }
            for (Map<String, Object> l : lineItems) {
                if (l.get("id") != null) {
                    jdbc.update("INSERT INTO invoice_line_item (id, invoice_id, description, qty, unit, unit_price, tax_exempt, discount_pct)"
                            + " VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                            ((Number) l.get("id")).longValue(), invoiceId, l.get("description"),
                            new BigDecimal(l.get("qty").toString()), l.get("unit"), new BigDecimal(l.get("unitPrice").toString()),
                            Boolean.TRUE.equals(l.get("taxExempt")), lineDiscountPct(l));
                } else {
                    jdbc.update("INSERT INTO invoice_line_item (invoice_id, description, qty, unit, unit_price, tax_exempt, discount_pct)"
                            + " VALUES (?, ?, ?, ?, ?, ?, ?)",
                            invoiceId, l.get("description"),
                            new BigDecimal(l.get("qty").toString()), l.get("unit"), new BigDecimal(l.get("unitPrice").toString()),
                            Boolean.TRUE.equals(l.get("taxExempt")), lineDiscountPct(l));
                }
            }
            // The scheduled instalments the invoice is split into, each an amount due on a date and maybe paid.
            for (Map<String, Object> n : rows(i, "instalments")) {
                jdbc.update("INSERT INTO invoice_instalment (id, invoice_id, amount, due_date, paid) VALUES (?, ?, ?, ?, ?)",
                        ((Number) n.get("id")).longValue(), invoiceId, new BigDecimal(n.get("amount").toString()),
                        LocalDate.parse(n.get("date").toString()), Boolean.TRUE.equals(n.get("paid")));
            }
        }
        // A payment in another currency ("currency") than its invoice's is converted into the invoice's currency at
        // the rates in effect on its date, and settles that much of the invoice.
-- The levy (the second tax) is scrapped: invoices carry only the one sales tax again, and every total
-- works out as if the levy never existed. An invoice that added a levy on top has it taken back out of
-- its stored amount (never below its minimum charge): the levy on each taxable line after its share of
-- the discounts, rounded to the cent and added up, just as it was charged. A tax-inclusive invoice owes
-- the same (the levy was inside its prices, and now only the sales tax is worked back out of them), and
-- a tax-exempt invoice never carried a levy.
CREATE VIEW invoice_levy_line_v109 AS
    SELECT l.invoice_id,
           l.tax_exempt,
           ROUND(l.qty * l.unit_price, 2) - ROUND(ROUND(l.qty * l.unit_price, 2) * l.discount_pct / 100, 2) AS line_amount
    FROM invoice_line_item l;

CREATE VIEW invoice_levy_subtotal_v109 AS
    SELECT i.id AS invoice_id,
           COALESCE((SELECT SUM(v.line_amount) FROM invoice_levy_line_v109 v WHERE v.invoice_id = i.id), 0) AS subtotal
    FROM invoice i;

-- The uncapped percentages each line takes off itself, and what the flat amounts and capped percentages
-- take off the subtotal together, shared across the lines in proportion to what each charges.
CREATE VIEW invoice_levy_discount_v109 AS
    SELECT s.invoice_id,
           s.subtotal,
           LEAST(COALESCE((SELECT SUM(d.discount_pct) FROM invoice_discount d WHERE d.invoice_id = s.invoice_id
                             AND d.discount_pct > 0
                             AND (d.discount_cap IS NULL OR ROUND(s.subtotal * d.discount_pct / 100, 2) <= d.discount_cap)), 0),
                 100) AS uncapped_pct,
           COALESCE((SELECT SUM(CASE WHEN d.discount_pct > 0 THEN d.discount_cap ELSE d.discount_amount END)
                     FROM invoice_discount d WHERE d.invoice_id = s.invoice_id
                       AND (d.discount_pct = 0
                            OR (d.discount_cap IS NOT NULL AND ROUND(s.subtotal * d.discount_pct / 100, 2) > d.discount_cap))), 0)
               AS shared_wanted
    FROM invoice_levy_subtotal_v109 s;

ALTER TABLE invoice ADD COLUMN rework_levy DECIMAL(14, 2);

UPDATE invoice i SET rework_levy = (
    SELECT COALESCE(SUM(ROUND(
               (v.line_amount
                - ROUND(v.line_amount * d.uncapped_pct / 100, 2)
                - CASE WHEN d.subtotal = 0 THEN 0
                       ELSE ROUND(LEAST(d.shared_wanted,
                                        GREATEST(d.subtotal - ROUND(d.subtotal * d.uncapped_pct / 100, 2), 0))
                                  * v.line_amount / d.subtotal, 2) END)
               * i.levy_pct / 100, 2)), 0)
    FROM invoice_levy_line_v109 v JOIN invoice_levy_discount_v109 d ON d.invoice_id = v.invoice_id
    WHERE v.invoice_id = i.id AND NOT v.tax_exempt)
WHERE i.levy_pct > 0
  AND NOT i.tax_inclusive
  AND NOT i.tax_exempt;

UPDATE invoice SET amount = GREATEST(amount - rework_levy, minimum_charge)
WHERE rework_levy IS NOT NULL AND rework_levy > 0;

ALTER TABLE invoice DROP COLUMN rework_levy;

DROP VIEW invoice_levy_discount_v109;
DROP VIEW invoice_levy_subtotal_v109;
DROP VIEW invoice_levy_line_v109;

ALTER TABLE invoice DROP CONSTRAINT invoice_levy_pct_range;
ALTER TABLE invoice DROP COLUMN levy_pct;
-- An invoice can carry the client's purchase-order number; unset when none was given.
ALTER TABLE invoice ADD COLUMN po_number VARCHAR(50);

package net.officefloor.hq.app.invoice;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.function.UnaryOperator;
import net.officefloor.hq.app.project.Project;

/**
 * An invoice raised against a project. It is built from line items, and can take several discounts off
 * their sum before tax, each either a percentage or a flat amount (the percentages each taking their share
 * of the subtotal first (a percentage capped at a maximum never taking off more than that), then the flat amounts, shared across the lines in proportion to what each
 * charges; together never more than the subtotal), then add a percentage sales tax on what is left of the taxable lines only
 * (tax-free lines are never taxed);
 * its stored amount is always that subtotal less the discount plus the tax, plus any flat
 * surcharge (such as a handling fee), which is added on last and is never taxed.
 * <p>
 * Every figure is worked out line by line: each line is rounded to the cent first and the rounded lines
 * are then added up, and the tax is likewise worked out and rounded on each taxable line before
 * being added up, so the totals are sums of rounded lines rather than a rounded sum.
 * <p>
 * A tax-inclusive invoice (for a client whose prices already include tax) instead works the tax
 * back out of the taxable lines after the discount: they are inside the price, so its amount is
 * just the subtotal less the discount (plus any surcharge), and the taxable base is what is left once they are taken out.
 * <p>
 * A tax-exempt invoice (for a tax-exempt client) has no taxable lines at all: it carries no tax
 * whatever its lines or rate say, so its amount is the subtotal less the discount (plus any surcharge).
 * <p>
 * An invoice can carry a minimum charge: when its net total (everything above, worked out as usual) comes
 * out under it, the minimum is billed instead, and the invoice records that the minimum was applied.
 */
@Entity
@Table(name = "invoice")
public class Invoice {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "project_id", nullable = false)
    private Project project;

    /** The currency the invoice is billed in when it differs from its client's; null means the client's currency. */
    @Column(length = 3)
    private String currency;

    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal amount = BigDecimal.ZERO.setScale(2);

    @Column(name = "tax_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal taxPct = BigDecimal.ZERO.setScale(2);

    /** A flat amount (such as a handling fee) added to the total after tax; zero when there is none. */
    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal surcharge = BigDecimal.ZERO.setScale(2);

    /** The least the invoice bills; zero when there is no minimum charge. */
    @Column(name = "minimum_charge", nullable = false, precision = 12, scale = 2)
    private BigDecimal minimumCharge = BigDecimal.ZERO.setScale(2);

    /** Whether the prices already include the tax, so it is backed out rather than added on. */
    @Column(name = "tax_inclusive", nullable = false)
    private boolean taxInclusive;

    /** Whether the invoice is for a tax-exempt client, so it carries no tax whatever its lines say. */
    @Column(name = "tax_exempt", nullable = false)
    private boolean taxExempt;

    /** The percentage taken off what is owed when paid early; zero when no early-payment discount is offered. */
    @Column(name = "early_payment_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal earlyPaymentPct = BigDecimal.ZERO.setScale(2);

    /** The percentage of the amount given back when paid before the due date; zero when no rebate is offered. */
    @Column(name = "rebate_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal rebatePct = BigDecimal.ZERO.setScale(2);

    /** The settlement rebate given back once the reduced amount was paid before the due date; zero until then. */
    @Column(name = "rebate_taken", nullable = false, precision = 12, scale = 2)
    private BigDecimal rebateTaken = BigDecimal.ZERO.setScale(2);

    /** The late fee charged for each day the invoice is overdue once sent; zero when none is charged. */
    @Column(name = "late_fee_per_day", nullable = false, precision = 12, scale = 2)
    private BigDecimal lateFeePerDay = BigDecimal.ZERO.setScale(2);

    @Column(name = "instalment_interest_per_day", nullable = false, precision = 12, scale = 2)
    private BigDecimal instalmentInterestPerDay = BigDecimal.ZERO.setScale(2);

    /** The percentage of the amount held back as retention, not due yet; zero when none is held back. */
    @Column(name = "retention_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal retentionPct = BigDecimal.ZERO.setScale(2);

    /** Whether the retention has been released, once the job is finished, so it is now due. */
    @Column(name = "retention_released", nullable = false)
    private boolean retentionReleased;

    /** The part of the invoice written off as bad debt, no longer owed; zero when none has been written off. */
    @Column(name = "write_off_amount", nullable = false, precision = 12, scale = 2)
    private BigDecimal writeOffAmount = BigDecimal.ZERO.setScale(2);

    /** The client's purchase-order number the invoice is raised against; null when none was given. */
    @Column(name = "po_number", length = 50)
    private String poNumber;

    /** Whether the client disputes the invoice; it still counts as owed, the flag only marks it. */
    @Column(nullable = false)
    private boolean disputed;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 16)
    private InvoiceStatus status = InvoiceStatus.DRAFT;

    @Column(name = "issued_date", nullable = false)
    private LocalDate issuedDate;

    @Column(name = "due_date", nullable = false)
    private LocalDate dueDate;

    @OneToMany(mappedBy = "invoice", cascade = CascadeType.ALL, orphanRemoval = true)
    @OrderBy("id")
    private List<InvoiceLineItem> lineItems = new ArrayList<>();

    /** The discounts taken off the subtotal before tax, in the order they were added. */
    @OneToMany(mappedBy = "invoice", cascade = CascadeType.ALL, orphanRemoval = true)
    @OrderBy("id")
    private List<InvoiceDiscount> discounts = new ArrayList<>();

    protected Invoice() {
    }

    public Invoice(Project project, LocalDate issuedDate, LocalDate dueDate) {
        this.project = project;
        this.issuedDate = issuedDate;
        this.dueDate = dueDate;
        this.taxInclusive = project.getClient().isTaxInclusive();
        this.taxExempt = project.getClient().isTaxExempt();
    }

    public Long getId() {
        return id;
    }

    public Project getProject() {
        return project;
    }

    /** The currency the invoice's money is in: its own, or else its client's. */
    public String getCurrency() {
        return currency != null ? currency : project.getClient().getCurrency();
    }

    public BigDecimal getAmount() {
        return amount;
    }

    /**
     * The total before tax: the amount owed less the sales tax, whether it was added on or is included
     * in the prices.
     */
    public BigDecimal getTotalExTax() {
        return amount.subtract(getTax());
    }

    /**
     * The overall tax rate that actually ended up on the invoice: the sales tax as a percentage of the
     * total before tax, to two decimal places. It is below the headline rates when some
     * lines are tax-free, and zero when there is nothing before tax to charge it on.
     */
    public BigDecimal getEffectiveTaxPct() {
        BigDecimal totalExTax = getTotalExTax();
        if (totalExTax.signum() == 0) {
            return BigDecimal.ZERO.setScale(2);
        }
        return getTax().multiply(BigDecimal.valueOf(100)).divide(totalExTax, 2, RoundingMode.HALF_UP);
    }

    /** The discounts on this invoice, in the order they were added. */
    public List<InvoiceDiscount> getDiscounts() {
        return List.copyOf(discounts);
    }

    /**
     * The percentages taken off the subtotal, added up (never more than 100); zero when there is no
     * percentage discount.
     */
    public BigDecimal getDiscountPct() {
        return discounts.stream().map(InvoiceDiscount::getDiscountPct).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add)
                .min(BigDecimal.valueOf(100).setScale(2));
    }

    /** The flat amounts asked to be taken off the subtotal, added up; zero when there is no flat discount. */
    public BigDecimal getDiscountAmount() {
        return discounts.stream().map(InvoiceDiscount::getDiscountAmount).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /**
     * How much one of this invoice's discounts actually takes off the subtotal, to the cent. The
     * percentages are taken first, each its share of the subtotal (never more than its cap, if it has
     * one), then the flat amounts in the order they were added; none takes off more than is left after
     * those before it.
     */
    public BigDecimal discountTakenBy(InvoiceDiscount discount) {
        BigDecimal subtotal = getSubtotal();
        BigDecimal left = subtotal;
        for (InvoiceDiscount d : discountsInOrderTaken()) {
            BigDecimal wanted = d.isPercentage() ? percentWanted(subtotal, d) : d.getDiscountAmount();
            BigDecimal taken = wanted.min(left.max(BigDecimal.ZERO.setScale(2)));
            if (d == discount) {
                return taken;
            }
            left = left.subtract(taken);
        }
        return BigDecimal.ZERO.setScale(2);
    }

    /** What a percentage discount asks to take off the subtotal: its share, never more than its cap. */
    private static BigDecimal percentWanted(BigDecimal subtotal, InvoiceDiscount discount) {
        BigDecimal share = percentOf(subtotal, discount.getDiscountPct());
        return isCappedAt(subtotal, discount) ? share.min(discount.getDiscountCap()) : share;
    }

    /** Whether a discount's cap limits what it takes off the given subtotal. */
    private static boolean isCappedAt(BigDecimal subtotal, InvoiceDiscount discount) {
        return discount.getDiscountCap() != null
                && percentOf(subtotal, discount.getDiscountPct()).compareTo(discount.getDiscountCap()) > 0;
    }

    /** The percentage discounts first, then the flat ones, each in the order they were added. */
    private List<InvoiceDiscount> discountsInOrderTaken() {
        List<InvoiceDiscount> ordered = new ArrayList<>(discounts.stream().filter(InvoiceDiscount::isPercentage).toList());
        ordered.addAll(discounts.stream().filter(d -> !d.isPercentage()).toList());
        return ordered;
    }

    /**
     * What the line items add up to, before the invoice's discount: the sum of each line after its own
     * discount, rounded to the cent.
     */
    public BigDecimal getSubtotal() {
        return lineItems.stream().map(InvoiceLineItem::getAmount).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** How much the discounts take off the subtotal together (what each takes off, added up), to the cent. */
    public BigDecimal getDiscount() {
        return discounts.stream().map(this::discountTakenBy).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /**
     * How much the client saves on this invoice: every discount added together, both what the lines take
     * off themselves and what the invoice's discounts take off the subtotal, to the cent.
     */
    public BigDecimal getTotalSavings() {
        BigDecimal lineSavings = lineItems.stream().map(l -> l.getGrossAmount().subtract(l.getAmount()))
                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        return lineSavings.add(getDiscount());
    }

    /** The sales tax percentage added after the discount; zero when there is no tax. */
    public BigDecimal getTaxPct() {
        return taxPct;
    }

    /** Whether the prices already include the tax, so it is worked back out rather than added on. */
    public boolean isTaxInclusive() {
        return taxInclusive;
    }

    /** Whether the invoice is for a tax-exempt client, so none of its lines are taxed. */
    public boolean isTaxExempt() {
        return taxExempt;
    }

    /**
     * What the sales tax is charged on: the taxable lines (leaving out tax-free ones) less the discount
     * taken off them, to the cent. On a tax-inclusive invoice that is what is left of them once the tax
     * inside them is taken out.
     */
    public BigDecimal getTaxableBase() {
        BigDecimal gross = getDiscountedTaxable();
        return taxInclusive ? gross.subtract(getTax()) : gross;
    }

    /**
     * How much sales tax is added on the taxable base (or is inside it, when tax-inclusive): the tax on
     * each taxable line rounded to the cent, added up.
     */
    public BigDecimal getTax() {
        return sumOverTaxableLines(this::taxOn);
    }

    /** The flat amount (such as a handling fee) added to the total after tax; zero when there is none. */
    public BigDecimal getSurcharge() {
        return surcharge;
    }

    /** The least this invoice bills; zero when there is no minimum charge. */
    public BigDecimal getMinimumCharge() {
        return minimumCharge;
    }

    /**
     * What the invoice comes to before any minimum charge: the subtotal less the discount plus the tax
     * (unless it is inside the prices), plus the surcharge.
     */
    public BigDecimal getNetTotal() {
        BigDecimal discounted = getSubtotal().subtract(getDiscount());
        return (taxInclusive ? discounted : discounted.add(getTax())).add(surcharge);
    }

    /** Whether the net total came out under the minimum charge, so the minimum is billed instead. */
    public boolean isMinimumApplied() {
        return getNetTotal().compareTo(minimumCharge) < 0;
    }

    /** The taxable lines (leaving out tax-free ones), each less the discount taken off it, added up. */
    private BigDecimal getDiscountedTaxable() {
        return sumOverTaxableLines(line -> line);
    }

    /**
     * Works a figure out on each taxable line after its discount, to the cent, and adds them up. A
     * tax-exempt invoice has no taxable lines.
     */
    private BigDecimal sumOverTaxableLines(UnaryOperator<BigDecimal> perLine) {
        return lineItems.stream().filter(l -> !taxExempt && !l.isTaxExempt()).map(InvoiceLineItem::getAmount)
                .map(amount -> perLine.apply(amount.subtract(discountOn(amount))))
                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /**
     * The part of a tax-inclusive price that is the given percentage, worked back out of it: the price
     * divided in proportion to the sales tax rate it includes (e.g. 20% tax in 120 is 20).
     */
    private BigDecimal includedIn(BigDecimal price, BigDecimal pct) {
        BigDecimal grossPct = BigDecimal.valueOf(100).add(taxPct);
        return price.multiply(pct).divide(grossPct, 2, RoundingMode.HALF_UP);
    }

    /** The percentage taken off what is owed when paid early; zero when none is offered. */
    public BigDecimal getEarlyPaymentPct() {
        return earlyPaymentPct;
    }

    /**
     * How many days after being issued the invoice must be paid within to get the early-payment discount:
     * the early-payment window in its client's payment terms; zero when the client has none.
     */
    public int getEarlyPaymentDays() {
        Integer window = project.getClient().getEarlyPaymentWindowDays();
        return window != null ? window : 0;
    }

    /** Whether an early-payment discount is offered: a percentage off when paid within the client's early-payment window. */
    public boolean offersEarlyPayment() {
        return earlyPaymentPct.signum() > 0 && getEarlyPaymentDays() > 0;
    }

    /** The last day the invoice can be paid to get the early-payment discount; null when none is offered. */
    public LocalDate getEarlyPaymentBy() {
        return offersEarlyPayment() ? issuedDate.plusDays(getEarlyPaymentDays()) : null;
    }

    /**
     * The reduced amount to pay when settling early: the amount less the early-payment percentage of it,
     * to the cent; null when no early-payment discount is offered.
     */
    public BigDecimal getEarlyPaymentAmount() {
        return offersEarlyPayment() ? amount.subtract(percentOf(amount, earlyPaymentPct)) : null;
    }

    /** The percentage of the amount given back when paid before the due date; zero when none is offered. */
    public BigDecimal getRebatePct() {
        return rebatePct;
    }

    /** The settlement rebate for paying before the due date: the rebate percentage of the amount, to the cent; null when none is offered. */
    public BigDecimal getRebate() {
        return rebatePct.signum() > 0 ? percentOf(amount, rebatePct) : null;
    }

    /** The settlement rebate given back because the client paid early enough; zero when it has not been earned. */
